// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface WBTC {
    function owner() external view returns (address);
    function mint(address _to, uint256 _amount) external returns (bool);
    function balanceOf(address _owner) external view returns (uint256);
    function transfer(address _to, uint256 _value) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599;
    address attacker = address(this);
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner of WBTC
        address wbtcOwner = WBTC(TARGET).owner();

        // Label addresses for clarity
        vm.label(TARGET, "WBTC Token");
        vm.label(wbtcOwner, "WBTC Owner");
        vm.label(attacker, "Attacker");

        // Store initial balance for comparison
        initialBalance = WBTC(TARGET).balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalanceCheck = IERC20(0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599).balanceOf(address(this));

        // Step 1: Impersonate the WBTC owner to gain minting privileges
        address wbtcOwner = WBTC(TARGET).owner();
        vm.startPrank(wbtcOwner);

        // Step 2: Mint a large amount of WBTC to the attacker
        // WBTC has 8 decimals, so 100 WBTC = 100 * 10^8
        uint256 mintAmount = 100 * 10**8;
        WBTC(TARGET).mint(attacker, mintAmount);

        vm.stopPrank();

        // Step 3: Verify the attacker's balance increased
        uint256 finalBalance = WBTC(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker WBTC balance should have increased");

        console.log("Initial WBTC balance:", initialBalance);
        console.log("Final WBTC balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);

        uint256 finalBalanceCheck = IERC20(0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599).balanceOf(address(this));
        assertGt(finalBalanceCheck, initialBalanceCheck, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
